SourceCode.Declaration:
/// <summary>
/// Vendor invoice journal form extension class.
/// </summary>
[ExtensionOf(formStr(VendInvoiceJournal))]
final class METVendInvoiceJournal_Extension
{
}

Method.Source:
/// <summary>
/// Enable/Disable the reprint CPN report button.
/// </summary>
public void init()
{
    next init();

    FormRun formRun = this;

    PurchTable purchReturn;

    if (formRun.args().caller() && formRun.args().dataset() == tableNum(PurchTable))
    {
        purchReturn = formRun.args().record();
    }

    FormControl control = formRun.design().controlName(formControlStr(VendInvoiceJournal, ContinuingPermissionNoticeReport));

    if (purchReturn.metPurchTable().ContinuingPermissionNoticeNumber)
    {
        control.visible(true);
    }
    else
    {
        control.visible(false);
    }
}
